<?php if(!defined('ABSPATH'))exit;if($role!=='admin'){echo '<p>Access denied.</p>';return;} global $wpdb;$rows=$wpdb->get_results("SELECT a.*,u.display_name FROM {$wpdb->prefix}rp_activity_log a LEFT JOIN {$wpdb->users} u ON u.ID=a.user_id ORDER BY a.id DESC LIMIT 200");?><h1 class="page-title">Activity Log</h1><div class="p-card"><p class="text-muted">Important actions performed inside the Spot panel are recorded here.</p><?php foreach($rows as $r):?><div class="order-item"><span class="order-num">#<?php echo (int)$r->id;?></span><div class="order-meta"><strong><?php echo esc_html($r->display_name?:'System');?> — <?php echo esc_html($r->action);?></strong><span class="text-sm text-muted"><?php echo esc_html($r->description);?> • <?php echo esc_html(wp_date('d M Y g:i A',strtotime($r->created_at)));?></span></div></div><?php endforeach;?></div>